1	/**
2	 * The map: tiles, wires, panning and zooming.
3	 *
4	 * The drawing library owns four things and no more — panning, zooming, working
5	 * out what is under the pointer, and the sockets on the sides of a tile.
6	 * Everything you can see is ours. That is why only the library's bare
7	 * stylesheet is imported below and never its full one: the full one carries the
8	 * library's own look, and a tool that looks like the library it was built with
9	 * looks like a demo. A check in `npm run lint` fails the build if the full one
10	 * ever appears in this tree.
11	 *
12	 * **Wires are plain here on purpose.** A wire is going to say five things at
13	 * once — what kind of push it is, how hard it pushes, whether it has to keep
14	 * holding, whether it loops back, and where it came from — and building that is
15	 * the next piece of work. What is drawn now is a deliberate placeholder: our
16	 * own stroke, our own arrowhead, one weight, so the shape of the map reads
17	 * while the wires still have nothing to say.
18	 */
19	
20	import {
21	  Background,
22	  BackgroundVariant,
23	  Controls,
24	  ReactFlow,
25	  ReactFlowProvider,
26	  useReactFlow,
27	} from "@xyflow/react";
28	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
29	import "@xyflow/react/dist/base.css";
30	import { Tile } from "../components/Tile";
31	import { TileOverflow } from "../components/TileOverflow";
32	import type { WorldView } from "../world";
33	import { FeedbackWire } from "./FeedbackWire";
34	import { LARGEST_ZOOM, SMALLEST_ZOOM, TILE_WIDTH } from "./geometry";
35	import { useLayout } from "./layoutRunner";
36	import { type ClaimNode, type MapEdge, type MapNode, type OverflowNode, toFlow } from "./toFlow";
37	import "./canvas.css";
38	
39	/** The two kinds of box the map draws. Defined once, outside render, so the
40	 * drawing library never has to rebuild its tiles because the object changed. */
41	const TILE_TYPES = {
42	  claim: ({ data }: { data: ClaimNode["data"] }) => (
43	    <Tile claim={data.claim} isHypothesis={data.isHypothesis} versions={data.versions} />
44	  ),
45	  overflow: ({ data }: { data: OverflowNode["data"] }) => <TileOverflow count={data.count} />,
46	};
47	
48	/** The one wire that is not drawn by the library's own router. */
49	const WIRE_TYPES = { feedback: FeedbackWire };
50	
51	/** How far above the highest tile the one backwards wire travels. */
52	const SKY_GAP = 56;
53	
54	/** The name of the arrowhead every wire ends in, defined once below. */
55	const ARROWHEAD = "katalyst-arrowhead";
56	
57	/**
58	 * How the map is framed the first time it is drawn: the whole of it — the one
59	 * backwards wire's run over the top included — with a margin of a twelfth of
60	 * the window around it, and never blown up past life size.
61	 *
62	 * The margin is as tight as it is on purpose. Whether the first frame shows the
63	 * full tiles or their summaries is decided by whether the whole map happens to
64	 * fit above the summary threshold, and a fat margin pushes a map that would
65	 * have fitted below it. On a window 1600 by 1000 this frames the stored example
66	 * at 0.88 — full tiles, with the smallest words landing at 11.4 pixels. On a
67	 * smaller window it lands below the threshold and the first frame is summaries,
68	 * which is the right answer there: the words stay legible and zooming in fills
69	 * the tiles.
70	 */
71	const FIRST_FRAME = { padding: 0.08, duration: 0 } as const;
72	
73	/** Never blown up past life size on the first frame, however small the map. */
74	const FIRST_FRAME_MAX_ZOOM = 1;
75	
76	/** The surface itself. Lives inside the provider so it can move the view. */
77	function MapSurface({ world }: { world: WorldView }) {
78	  const flow = useReactFlow();
79	  const surface = useRef<HTMLDivElement>(null);
80	  const [focused, setFocused] = useState<string | null>(null);
81	
82	  const drawing = useMemo(() => toFlow(world), [world]);
83	  const layout = useLayout(drawing.tiles, drawing.layoutEdges);
84	
85	  const nodes: MapNode[] = useMemo(
86	    () =>
87	      drawing.nodes.map((node) => ({
88	        ...node,
89	        position: layout.positions.get(node.id) ?? { x: 0, y: 0 },
90	      })),
91	    [drawing, layout],
92	  );
93	
94	  // The one backwards wire travels above every tile, so it needs to be told
95	  // where the top of the map is. An edge cannot see the other tiles.
96	  const edges: MapEdge[] = useMemo(() => {
97	    const tops = [...layout.positions.values()].map((at) => at.y);
98	    const skyY = (tops.length > 0 ? Math.min(...tops) : 0) - SKY_GAP;
99	    return drawing.edges.map((edge) => {
100	      if (edge.type !== "feedback" || edge.data === undefined) {
101	        return edge;
102	      }
103	      return { ...edge, data: { ...edge.data, skyY } };
104	    });
105	  }, [drawing, layout]);
106	
107	  /** How tall a tile turned out to be, so the view can be centred on its middle. */
108	  const heightOf = useCallback(
109	    (id: string) => drawing.tiles.find((tile) => tile.id === id)?.height ?? 0,
110	    [drawing],
111	  );
112	
113	  /**
114	   * Everything the first frame has to hold: every tile, and the strip of empty
115	   * space above them that the one backwards wire runs along.
116	   */
117	  const mapBounds = useCallback(() => {
