39	
40	/** How far the wire stands off a tile before it turns. */
41	const STANDOFF = 24;
42	
43	/** How round the corners are. */
44	const CORNER = 8;
45	
46	/**
47	 * Draw a path through these corners, with the corners rounded off.
48	 *
49	 * Each turn is cut back along both of its arms and joined with a curve, so the
50	 * wire bends rather than snapping. A corner is never cut back further than half
51	 * the arm it sits on, so two turns close together cannot cross each other.
52	 *
53	 * @param points The corners, in order, starting and ending at the two sockets.
54	 */
55	export function roundedPath(points: readonly (readonly [number, number])[]): string {
56	  const first = points[0];
57	  const last = points[points.length - 1];
58	  if (first === undefined || last === undefined) {
59	    return "";
60	  }
61	  let path = `M ${first[0]},${first[1]}`;
62	  for (let i = 1; i < points.length - 1; i += 1) {
63	    const before = points[i - 1];
64	    const here = points[i];
65	    const after = points[i + 1];
