72	    const startX = here[0] + ((before[0] - here[0]) / (inLength || 1)) * cut;
73	    const startY = here[1] + ((before[1] - here[1]) / (inLength || 1)) * cut;
74	    const endX = here[0] + ((after[0] - here[0]) / (outLength || 1)) * cut;
75	    const endY = here[1] + ((after[1] - here[1]) / (outLength || 1)) * cut;
76	    path += ` L ${startX},${startY} Q ${here[0]},${here[1]} ${endX},${endY}`;
77	  }
78	  return `${path} L ${last[0]},${last[1]}`;
