1	/*
2	 * The map surface.
3	 *
4	 * The drawing library ships two stylesheets. The bare one, which this app
5	 * imports, is the handful of rules without which panning and zooming do not
6	 * work: positions, transform origins, pointer handling. The full one carries
7	 * the library's own look — its blue handles, its white boxes, its rounded
8	 * buttons — and is never imported here. What that leaves is a set of the
9	 * library's own custom properties, listed below, which is how a look is handed
10	 * over rather than overridden.
11	 */
12	
13	.canvas {
14	  position: relative;
15	  flex: 1 1 auto;
16	  min-height: 0;
17	  background: var(--surface);
18	}
19	
20	/* The library's own settings, set to ours. */
21	.canvas .react-flow {
22	  --xy-edge-stroke: var(--text-muted);
23	  --xy-edge-stroke-width: 1.25;
24	  --xy-background-color: var(--surface);
25	  --xy-background-pattern-color: var(--hairline);
26	  --xy-attribution-background-color: transparent;
27	}
28	
29	/* Where our own drawing marks are defined. No size and no ink of its own; the
30	 * wires reach into it for the arrowhead. */
31	.canvas__marks {
32	  position: absolute;
33	  width: 0;
34	  height: 0;
35	  overflow: hidden;
36	}
37	
38	.canvas__marks marker path {
39	  fill: none;
40	  stroke: var(--text-muted);
41	  stroke-width: 1.4;
42	  stroke-linecap: round;
43	  stroke-linejoin: round;
44	}
45	
46	/* ---- Wires, plainly ----------------------------------------------------- *
47	 * One weight, one colour, our arrowhead. A wire is about to carry five
48	 * different things at once — what kind of push it is, how hard, whether it has
49	 * to keep holding, whether it loops back, and where it came from — and none of
50	 * that is built yet. Drawing a placeholder that already looked encoded would be
51	 * worse than drawing a plain line, because a reader would try to read it. */
52	
53	.canvas .react-flow__edge-path {
54	  stroke-linecap: round;
55	}
56	
57	/* ---- Tiles -------------------------------------------------------------- */
58	
59	/* A tile the keyboard is on. The ring is ours, drawn the same way as every
60	 * other focus ring in the app, and it sits outside the tile's own outline so
61	 * that it never hides the shape that says what kind of claim it is. */
62	.canvas .react-flow__node:focus-visible {
63	  outline: 2px solid var(--focus);
64	  outline-offset: 4px;
65	  border-radius: 2px;
66	}
67	
68	/* A tile whose belief chip has opened its shelf has to be drawn over the tile
69	 * below it, or the shelf would slide out behind its neighbour. The drawing
70	 * library writes each tile's stacking order straight onto the element, and a
71	 * value written onto an element beats any rule written in a stylesheet — so
72	 * this one rule has to insist, and it is the only one in the product that does. */
73	.canvas .react-flow__node:has(.belief-chip:hover),
74	.canvas .react-flow__node:has(.belief-chip:focus-within),
75	.canvas .react-flow__node:has(.belief-chip__note[data-pinned="yes"]) {
76	  /* biome-ignore lint/complexity/noImportantStyles: the drawing library writes this tile's stacking order onto the element itself, and nothing in a stylesheet can otherwise reach past it. */
77	  z-index: 20 !important;
78	}
79	
80	/* ---- The library's own furniture ---------------------------------------- *
81	 * Two pieces survive with the bare stylesheet: the zoom buttons and the
82	 * library's attribution link. Both are given our type, our colours and our
83	 * hairlines, so neither reads as somebody else's component. */
84	
85	.canvas .react-flow__controls {
86	  box-shadow: none;
87	  border: 1px solid var(--hairline);
88	  border-radius: var(--radius);
89	  overflow: hidden;
90	  background: var(--surface-raised);
91	  margin: var(--space-2);
92	}
93	
94	.canvas .react-flow__controls-button {
95	  width: var(--space-4);
96	  height: var(--space-4);
97	  max-width: none;
98	  max-height: none;
99	  padding: var(--space-1);
100	  border: none;
101	  background: var(--surface-raised);
102	  color: var(--text-muted);
103	  cursor: pointer;
104	}
105	
106	.canvas .react-flow__controls-button + .react-flow__controls-button {
107	  border-top: 1px solid var(--hairline);
108	}
109	
110	.canvas .react-flow__controls-button:hover {
111	  color: var(--text);
112	}
113	
114	.canvas .react-flow__controls-button svg {
115	  max-width: 12px;
116	  max-height: 12px;
117	  fill: currentColor;
118	}
119	
120	/* The library asks to be named, and it should be. What it may not do is set the
121	 * type size: ten pixels is below the smallest size anything in this product is
122	 * allowed to be drawn at. */
123	.canvas .react-flow__attribution {
124	  font-size: var(--text-sm);
125	  padding: var(--space-hair) var(--space-1);
126	}
127	
128	.canvas .react-flow__attribution a {
129	  color: var(--text-muted);
130	}
131	
132	/* ---- When the layout fails ---------------------------------------------- *
133	 * Printed on the surface, in the sentence the layout engine gave. Not a pop-up:
134	 * there is nothing to dismiss and nothing behind it stops working. */
135	
136	.canvas__failure {
137	  position: absolute;
138	  left: var(--space-2);
139	  bottom: var(--space-2);
140	  right: var(--space-2);
141	  margin: 0;
142	  padding: var(--space-1) var(--space-2);
143	  background: var(--surface-raised);
144	  border: 1px solid var(--hairline);
145	  border-radius: var(--radius);
146	  font-size: var(--text-sm);
147	  color: var(--text);
148	}
149	
150	/* ---- The one wire that runs backwards ----------------------------------- *
151	 * A feedback arrow is the only one allowed to point the other way, and it is
152	 * routed over the top of the map so that it never crosses a tile. The dashes
153	 * say one thing and one thing only — *this one runs backwards* — and they are a
154	 * placeholder: the work that gives the stroke its real job, saying what kind of
155	 * push a wire carries, replaces this with a loop and the delay written on it. */
156	
157	.canvas .wire--feedback {
158	  stroke-dasharray: 2 5;
159	  stroke-linecap: round;
160	}
161

