1	/**
2	 * The whole screen: the launchpad, and the map you open from it.
3	 *
4	 * Two states and nothing in between. The launchpad names the two ways into the
5	 * tool and offers the four examples from the brief; opening the one that is
6	 * built swaps the page for the map. Everything on the map came over the wire
7	 * from the server, and the line under it says which address it came from — this
8	 * product does not put a number on screen that a reader cannot trace to an
9	 * input, a rule or a source, and that includes numbers a stored example happens
10	 * to carry.
11	 *
12	 * There is no spinner anywhere, and there never will be. A spinner says "wait"
13	 * without saying what for. While something is on its way the screen says what
14	 * it is waiting for and where it asked.
15	 */
16	
17	import { useCallback, useEffect, useMemo, useState } from "react";
18	import type { About, FixtureSummary, Health, Readiness } from "./api/client";
19	import { readAbout, readExampleList, readHealth, readReadiness } from "./api/client";
20	import { Launchpad } from "./components/Launchpad";
21	import { MapCanvas } from "./graph/Canvas";
22	import { FixtureWorldSource, type WorldSource, type WorldView } from "./world";
23	
24	/**
25	 * Everything the screen can know about one thing it asked for. Three states and
26	 * no others, which is what makes every pixel below traceable to a cause.
27	 */
28	type Answer<Reading> =
29	  | { state: "asking" }
30	  | { state: "answered"; value: Reading }
31	  | { state: "failed"; reason: string };
32	
33	/** How loud a row's words are. Emphasis only — the words carry the meaning. */
34	type Tone = "good" | "quiet" | "loud";
35	
36	/** One row of the strip at the foot of the launchpad. */
37	interface Reading {
38	  /** What is being reported, such as "server". */
39	  label: string;
40	  /** The value from the server, or null while the request is still in flight. */
41	  value: string | null;
42	  /** A mark beside the words. Never the only carrier of meaning. */
43	  glyph: string;
44	  /** What the value means, in plain words. On a failure, this is the failure. */
45	  state: string;
46	  tone: Tone;
47	}
48	
49	/** Turn whatever a failed request threw into one sentence. */
50	function inWords(reason: unknown): string {
51	  return reason instanceof Error ? reason.message : "The reason was not recorded.";
52	}
53	
54	/**
55	 * Make one request when the screen first appears and report where it got to.
56	 *
57	 * @param ask The request to make. It must be the same function on every render,
58	 *   so pass one defined at module level rather than one written inline.
59	 */
60	function useAnswer<Reading>(ask: () => Promise<Reading>): Answer<Reading> {
61	  const [answer, setAnswer] = useState<Answer<Reading>>({ state: "asking" });
62	
63	  useEffect(() => {
64	    let stillOnScreen = true;
65	    ask().then(
66	      (value) => {
67	        if (stillOnScreen) {
68	          setAnswer({ state: "answered", value });
69	        }
70	      },
71	      (reason: unknown) => {
72	        if (stillOnScreen) {
73	          setAnswer({ state: "failed", reason: inWords(reason) });
74	        }
75	      },
76	    );
77	    return () => {
78	      stillOnScreen = false;
79	    };
80	  }, [ask]);
81	
82	  return answer;
83	}
84	
85	/** The row that says whether the server answered at all. */
86	function serverReading(answer: Answer<Health>): Reading {
87	  switch (answer.state) {
88	    case "asking":
89	      return {
90	        label: "server",
91	        value: null,
92	        glyph: "○",
93	        state: "asking the server",
94	        tone: "quiet",
95	      };
96	    case "answered":
97	      return {
98	        label: "server",
99	        value: answer.value.status,
100	        glyph: "●",
101	        state: "reachable",
102	        tone: "good",
103	      };
104	    case "failed":
105	      return { label: "server", value: "—", glyph: "○", state: answer.reason, tone: "loud" };
106	  }
107	}
108	
109	/** The row that says whether a key for the language model is configured. */
110	function modelKeyReading(answer: Answer<Readiness>): Reading {
111	  switch (answer.state) {
112	    case "asking":
113	      return {
114	        label: "model key",
115	        value: null,
116	        glyph: "○",
117	        state: "asking the server",
118	        tone: "quiet",
119	      };
120	    case "answered":
121	      return answer.value.model_key_present
122	        ? {
123	            label: "model key",
124	            value: "present",
125	            glyph: "●",
126	            state: "ready to generate",
127	            tone: "good",
128	          }
129	        : {
130	            label: "model key",
131	            value: "absent",
132	            glyph: "○",
133	            state: "no key configured — generating a map is not built yet",
134	            tone: "quiet",
135	          };
136	    case "failed":
137	      return { label: "model key", value: "—", glyph: "○", state: answer.reason, tone: "loud" };
138	  }
139	}
140	
141	/** The row that says which build answered. */
142	function versionReading(answer: Answer<About>): Reading {
143	  switch (answer.state) {
144	    case "asking":
145	      return {
146	        label: "version",
147	        value: null,
148	        glyph: "○",
149	        state: "asking the server",
150	        tone: "quiet",
151	      };
152	    case "answered":
153	      return {
154	        label: "version",
155	        value: answer.value.version,
156	        glyph: "●",
157	        state: `reported by ${answer.value.name}`,
158	        tone: "good",
159	      };
160	    case "failed":
161	      return { label: "version", value: "—", glyph: "○", state: answer.reason, tone: "loud" };
162	  }
163	}
164	
165	/**
166	 * Why the three examples that need the model are not live, in one sentence.
167	 *
168	 * Read from the server's own answer rather than written into the page, so that
169	 * the reason on screen is the real one.
170	 */
171	function notLiveReason(answer: Answer<Readiness>): string {
172	  if (answer.state === "answered" && !answer.value.model_key_present) {
173	    return "Turning your own words into a map needs the model, and this server has no key for one.";
174	  }
175	  return "Turning your own words into a map is not built yet.";
176	}
177	
178	/**
179	 * One row: a label, the value the server gave, and what that value means.
180	 *
