187	  return (
188	    <div className="status-row">
189	      <dt className="status-label">{reading.label}</dt>
190	      <dd className="status-value" data-settled={waiting ? "no" : "yes"}>
191	        {waiting ? <span className="placeholder" aria-hidden="true" /> : reading.value}
192	      </dd>
193	      <dd className="status-state" data-tone={reading.tone}>
194	        <span className="glyph" aria-hidden="true">
195	          {reading.glyph}
196	        </span>
197	        <span className="state-words">{reading.state}</span>
198	      </dd>
199	    </div>
200	  );
201	}
202	
203	/** Which of the two screens is showing. */
204	type Screen =
205	  | { at: "launchpad" }
206	  | { at: "opening"; id: string }
207	  | { at: "map"; world: WorldView }
208	  | { at: "failed"; id: string; reason: string };
209	
210	/**
211	 * Where maps come from.
212	 *
213	 * Today this reads the stored example the server ships with. When the engine's
214	 * world route lands, this one line becomes `new ApiWorldSource()` and every
215	 * number slot that reads as an absence today fills in. Nothing else on this
216	 * screen changes, which is the whole reason there is a seam here at all.
217	 */
218	const DEFAULT_SOURCE: WorldSource = new FixtureWorldSource();
219	
220	/** What the screen needs. Both have defaults; both exist so they can be swapped. */
221	export interface AppProps {
222	  /** Where maps and worlds come from. */
223	  readonly source?: WorldSource;
224	  /** How the list of stored examples is read. */
225	  readonly listExamples?: () => Promise<FixtureSummary[]>;
226	}
227	
228	/** The screen. */
229	export function App({ source = DEFAULT_SOURCE, listExamples = readExampleList }: AppProps = {}) {
230	  const health = useAnswer(readHealth);
231	  const readiness = useAnswer(readReadiness);
232	  const about = useAnswer(readAbout);
