/**
 * The whole screen: the launchpad, and the map you open from it.
 *
 * Two states and nothing in between. The launchpad names the two ways into the
 * tool and offers the four examples from the brief; opening the one that is
 * built swaps the page for the map. Everything on the map came over the wire
 * from the server, and the line under it says which address it came from — this
 * product does not put a number on screen that a reader cannot trace to an
 * input, a rule or a source, and that includes numbers a stored example happens
 * to carry.
 *
 * There is no spinner anywhere, and there never will be. A spinner says "wait"
 * without saying what for. While something is on its way the screen says what
 * it is waiting for and where it asked.
 */

import { useCallback, useEffect, useMemo, useState } from "react";
import type { About, FixtureSummary, Health, Readiness } from "./api/client";
import { readAbout, readExampleList, readHealth, readReadiness } from "./api/client";
import { Launchpad } from "./components/Launchpad";
import { MapCanvas } from "./graph/Canvas";
import { FixtureWorldSource, type WorldSource, type WorldView } from "./world";

/**
 * Everything the screen can know about one thing it asked for. Three states and
 * no others, which is what makes every pixel below traceable to a cause.
 */
type Answer<Reading> =
  | { state: "asking" }
  | { state: "answered"; value: Reading }
  | { state: "failed"; reason: string };

/** How loud a row's words are. Emphasis only — the words carry the meaning. */
type Tone = "good" | "quiet" | "loud";

/** One row of the strip at the foot of the launchpad. */
interface Reading {
  /** What is being reported, such as "server". */
  label: string;
  /** The value from the server, or null while the request is still in flight. */
  value: string | null;
  /** A mark beside the words. Never the only carrier of meaning. */
  glyph: string;
  /** What the value means, in plain words. On a failure, this is the failure. */
  state: string;
  tone: Tone;
}

/** Turn whatever a failed request threw into one sentence. */
function inWords(reason: unknown): string {
  return reason instanceof Error ? reason.message : "The reason was not recorded.";
}

/**
 * Make one request when the screen first appears and report where it got to.
 *
 * @param ask The request to make. It must be the same function on every render,
 *   so pass one defined at module level rather than one written inline.
 */
function useAnswer<Reading>(ask: () => Promise<Reading>): Answer<Reading> {
  const [answer, setAnswer] = useState<Answer<Reading>>({ state: "asking" });

  useEffect(() => {
    let stillOnScreen = true;
    ask().then(
      (value) => {
        if (stillOnScreen) {
          setAnswer({ state: "answered", value });
        }
      },
      (reason: unknown) => {
        if (stillOnScreen) {
          setAnswer({ state: "failed", reason: inWords(reason) });
        }
      },
    );
    return () => {
      stillOnScreen = false;
    };
  }, [ask]);

  return answer;
}

/** The row that says whether the server answered at all. */
function serverReading(answer: Answer<Health>): Reading {
  switch (answer.state) {
    case "asking":
      return {
        label: "server",
        value: null,
        glyph: "○",
        state: "asking the server",
        tone: "quiet",
      };
    case "answered":
      return {
        label: "server",
        value: answer.value.status,
        glyph: "●",
        state: "reachable",
        tone: "good",
      };
    case "failed":
      return { label: "server", value: "—", glyph: "○", state: answer.reason, tone: "loud" };
  }
}

/** The row that says whether a key for the language model is configured. */
function modelKeyReading(answer: Answer<Readiness>): Reading {
  switch (answer.state) {
    case "asking":
      return {
        label: "model key",
        value: null,
        glyph: "○",
        state: "asking the server",
        tone: "quiet",
      };
    case "answered":
      return answer.value.model_key_present
        ? {
            label: "model key",
            value: "present",
            glyph: "●",
            state: "ready to generate",
            tone: "good",
          }
        : {
            label: "model key",
            value: "absent",
            glyph: "○",
            state: "no key configured — generating a map is not built yet",
            tone: "quiet",
          };
    case "failed":
      return { label: "model key", value: "—", glyph: "○", state: answer.reason, tone: "loud" };
  }
}

/** The row that says which build answered. */
function versionReading(answer: Answer<About>): Reading {
  switch (answer.state) {
    case "asking":
      return {
        label: "version",
        value: null,
        glyph: "○",
        state: "asking the server",
        tone: "quiet",
      };
    case "answered":
      return {
        label: "version",
        value: answer.value.version,
        glyph: "●",
        state: `reported by ${answer.value.name}`,
        tone: "good",
      };
    case "failed":
      return { label: "version", value: "—", glyph: "○", state: answer.reason, tone: "loud" };
  }
}

/**
 * Why the three examples that need the model are not live, in one sentence.
 *
 * Read from the server's own answer rather than written into the page, so that
 * the reason on screen is the real one.
 */
function notLiveReason(answer: Answer<Readiness>): string {
  if (answer.state === "answered" && !answer.value.model_key_present) {
    return "Turning your own words into a map needs the model, and this server has no key for one.";
  }
  return "Turning your own words into a map is not built yet.";
}

/**
 * One row: a label, the value the server gave, and what that value means.
 *
 * While the value is missing the cell holds a bar of the same height, so the
 * row does not change size when the answer arrives. There is no spinner: a bar
 * where the value will land says the same thing without pretending to spin.
 */
function StatusRow({ reading }: { reading: Reading }) {
  const waiting = reading.value === null;
  return (
    <div className="status-row">
      <dt className="status-label">{reading.label}</dt>
      <dd className="status-value" data-settled={waiting ? "no" : "yes"}>
        {waiting ? <span className="placeholder" aria-hidden="true" /> : reading.value}
      </dd>
      <dd className="status-state" data-tone={reading.tone}>
        <span className="glyph" aria-hidden="true">
          {reading.glyph}
        </span>
        <span className="state-words">{reading.state}</span>
      </dd>
    </div>
  );
}

/** Which of the two screens is showing. */
type Screen =
  | { at: "launchpad" }
  | { at: "opening"; id: string }
  | { at: "map"; world: WorldView }
  | { at: "failed"; id: string; reason: string };

/**
 * Where maps come from.
 *
 * Today this reads the stored example the server ships with. When the engine's
 * world route lands, this one line becomes `new ApiWorldSource()` and every
 * number slot that reads as an absence today fills in. Nothing else on this
 * screen changes, which is the whole reason there is a seam here at all.
 */
const DEFAULT_SOURCE: WorldSource = new FixtureWorldSource();

/** What the screen needs. Both have defaults; both exist so they can be swapped. */
export interface AppProps {
  /** Where maps and worlds come from. */
  readonly source?: WorldSource;
  /** How the list of stored examples is read. */
  readonly listExamples?: () => Promise<FixtureSummary[]>;
}

/** The screen. */
export function App({ source = DEFAULT_SOURCE, listExamples = readExampleList }: AppProps = {}) {
  const health = useAnswer(readHealth);
  const readiness = useAnswer(readReadiness);
  const about = useAnswer(readAbout);
  const examples = useAnswer(listExamples);

  const [screen, setScreen] = useState<Screen>({ at: "launchpad" });

  const open = useCallback(
    (id: string) => {
      setScreen({ at: "opening", id });
      source.readWorld({ baseId: id }).then(
        (world) => setScreen({ at: "map", world }),
        (reason: unknown) => setScreen({ at: "failed", id, reason: inWords(reason) }),
      );
    },
    [source],
  );

  const toLaunchpad = useCallback(() => setScreen({ at: "launchpad" }), []);

  const readings = useMemo(
    () => [serverReading(health), modelKeyReading(readiness), versionReading(about)],
    [health, readiness, about],
  );

  if (screen.at !== "launchpad") {
    return (
      <main className="page page--map">
        <header className="map-bar">
          <button className="map-bar__back" type="button" onClick={toLaunchpad}>
            <span aria-hidden="true">←</span> Back to the launchpad
          </button>
          <h1 className="map-bar__title">
            {screen.at === "map" ? screen.world.title : "Strait of Hormuz"}
          </h1>
        </header>

        {screen.at === "map" ? (
          <>
            <MapCanvas world={screen.world} />
            <p className="map-origin">{screen.world.origin}</p>
          </>
        ) : (
          <div className="map-waiting">
            <p className="map-waiting__line">
              {screen.at === "opening"
                ? `Reading the stored map from /api/fixtures/${screen.id}.`
                : screen.reason}
            </p>
          </div>
        )}
      </main>
    );
  }

  return (
    <main className="page">
      <div className="column">
        <header className="masthead">
          <h1 className="wordmark">Katalyst</h1>
          <p className="purpose">
            Type an event you think will happen. See what it would cause, step by step, ending in
            trades.
          </p>
        </header>

        <Launchpad
          examples={examples.state === "answered" ? examples.value : null}
          failure={examples.state === "failed" ? examples.reason : null}
          notLiveReason={notLiveReason(readiness)}
          onOpen={open}
        />

        <section aria-labelledby="status-heading">
          <h2 className="section-heading" id="status-heading">
            What this build can do right now
          </h2>
          <dl className="status-strip">
            {readings.map((reading) => (
              <StatusRow key={reading.label} reading={reading} />
            ))}
          </dl>
          <p className="provenance">
            Every reading above came from the server, at <code>/api/healthz</code>,{" "}
            <code>/api/readyz</code> and <code>/api/about</code>. The examples came from{" "}
            <code>/api/fixtures</code>. Nothing on this screen is written into the page.
          </p>
        </section>
      </div>
    </main>
  );
}

/**
 * A claim, as a card on the map.
 *
 * A tile shows six things and no more, because a seventh always arrives at the
 * cost of the six:
 *
 *   1. the claim, wrapping to three lines and then stopping — never cut in the
 *      middle of a word;
 *   2. three belief chips, the model's, the reader's and a market's, side by
 *      side and never averaged;
 *   3. at most two evidence clippings, each a letter standing for a publication
 *      and one line of what it says;
 *   4. the day the claim is settled by;
 *   5. its outline, which says what kind of claim it is — shape carries that,
 *      never colour;
 *   6. a place for its badges, which arrive with the buttons that earn them.
 *
 * The rest — the full claim, the resolution criteria, the sources, the
 * reasoning behind a number — belongs in the panel beside the map, which is
 * built in the pull request after this one.
 *
 * **The outline is drawn rather than bordered.** The tile has no border of its
 * own; a line drawing sits behind it with a one-pixel stroke at a tenth of the
 * text colour, and its path is what makes a hypothesis look different from a
 * dead end. Four shapes, four kinds, and the shapes survive being printed in
 * grey — which a colour never does.
 */

import { Handle, Position, useStore } from "@xyflow/react";
import { claimLines, SUMMARY_BELOW_ZOOM, TILE_WIDTH, tileHeight } from "../graph/geometry";
import type { ClaimKind, ClaimView } from "../world";
import { BeliefChip } from "./BeliefChip";
import "./tile.css";

/**
 * The four outlines, as line drawings the width and height of a tile.
 *
 * Each one is drawn to the height its own tile turned out to be, because a tile
 * is as tall as its content. Every path is offset by half a pixel so that a
 * one-pixel stroke lands on a pixel boundary instead of straddling two and
 * going soft.
 *
 * - **hypothesis** — the left edge comes to a point. This is where the map
 *   starts: the claim the reader typed, with nothing before it.
 * - **event** — an ordinary rounded box. A step in the middle of the chain.
 * - **market** — the top right corner is cut away, the way a ticket is. There
 *   is something here you could actually trade.
 * - **not tradeable** — the right edge is notched inward. The chain really does
 *   end here, and there is nothing to plug into it.
 *
 * Two of the four cut into the space a word would sit in, so those two tiles are
 * given a wider margin on that side — see `tile.css`. A shape that crosses its
 * own words is not a shape, it is a mistake.
 */
const OUTLINES: Record<ClaimKind, (height: number) => string> = {
  hypothesis: (h) => `M 16.5 0.5 H ${TILE_WIDTH - 0.5} V ${h - 0.5} H 16.5 L 0.5 ${h / 2} Z`,
  event: (h) =>
    `M 6.5 0.5 H ${TILE_WIDTH - 6.5} A 6 6 0 0 1 ${TILE_WIDTH - 0.5} 6.5 V ${h - 6.5} ` +
    `A 6 6 0 0 1 ${TILE_WIDTH - 6.5} ${h - 0.5} H 6.5 A 6 6 0 0 1 0.5 ${h - 6.5} ` +
    `V 6.5 A 6 6 0 0 1 6.5 0.5 Z`,
  market: (h) => `M 0.5 0.5 H ${TILE_WIDTH - 18.5} L ${TILE_WIDTH - 0.5} 18.5 V ${h - 0.5} H 0.5 Z`,
  not_tradeable: (h) =>
    `M 0.5 0.5 H ${TILE_WIDTH - 0.5} V ${h / 2 - 14} L ${TILE_WIDTH - 14.5} ${h / 2} ` +
    `L ${TILE_WIDTH - 0.5} ${h / 2 + 14} V ${h - 0.5} H 0.5 Z`,
};

/** What each kind is called on screen. No underscores and no code names. */
const KIND_WORDS: Record<ClaimKind, string> = {
  hypothesis: "hypothesis",
  event: "event",
  market: "market",
  not_tradeable: "not tradeable",
};

/**
 * Print a date the way the map prints one: `Nov 1`.
 *
 * Read as a day in the map's own reckoning rather than in the reader's time
 * zone, because a claim settled on the first of November is settled on the
 * first of November wherever the reader happens to be sitting.
 */
export function toDay(isoDate: string): string {
  const parsed = new Date(`${isoDate}T00:00:00Z`);
  if (Number.isNaN(parsed.getTime())) {
    return isoDate;
  }
  return new Intl.DateTimeFormat("en", {
    month: "short",
    day: "numeric",
    timeZone: "UTC",
  }).format(parsed);
}

/** One published item, as a clipping: a letter for the publication and one line. */
function Clipping({
  monogram,
  host,
  line,
  direction,
}: {
  monogram: string;
  host: string;
  line: string;
  direction: 1 | -1;
}) {
  // A sign, not a colour: "+" for an item that supports the claim, "−" for one
  // that cuts against it. A reader who cannot tell two hues apart loses nothing.
  const sign = direction === 1 ? "+" : "−";
  const inWords = direction === 1 ? "supports this claim" : "cuts against this claim";
  return (
    <li className="tile__clipping">
      <span className="tile__monogram" aria-hidden="true">
        {monogram}
      </span>
      <span className="tile__clipping-sign" aria-hidden="true">
        {sign}
      </span>
      <span className="tile__clipping-line">
        <span className="tile__hidden">{`${host}, ${inWords}: `}</span>
        {line}
      </span>
    </li>
  );
}

/** What a tile needs to draw itself. */
export interface TileProps {
  /** The claim this tile is for. */
  readonly claim: ClaimView;
  /** True when this claim is the one the reader started from. */
  readonly isHypothesis: boolean;
  /**
   * How many versions of the map were run to produce this world's numbers.
   *
   * Absent means nothing computed them, and the model chip says so instead of
   * describing a run that never happened.
   */
  readonly versions?: number;
}

/** One claim's tile. */
export function Tile({ claim, isHypothesis, versions }: TileProps) {
  // How far the map is zoomed out. Below the threshold a tile stops showing
  // everything and shows a summary instead — the claim and the three chips —
  // because the alternative is type too small to read. The tile changes what it
  // draws; it never shrinks what it draws.
  const zoom = useStore((state) => state.transform[2]);
  const detail = zoom < SUMMARY_BELOW_ZOOM ? "summary" : "full";

  // Only one claim in four prints why it has no market: the kind that ends the
  // map without an instrument. That reason is a finding — somebody looked and
  // wrote down what they found — and it belongs on the face of the tile. For
  // every other claim "no market" is a fact about the world's plumbing, the
  // chip says it in two words, and the sentence behind it is on the chip's
  // shelf and in what the chip is called when it is read out loud.
  const finding = claim.kind === "not_tradeable" ? claim.beliefs.market.absence : undefined;
  // As tall as this claim's own content, worked out the same way the layout
  // worked it out, so the box the map reserved and the box the browser draws
  // are the same box.
  const height = tileHeight(claim);
  const lines = claimLines(claim.claim);
  // The foot only exists when it has something in it. An empty one would still
  // take a gap above it, and the tile would have a step of dead space at the
  // bottom — which is the whole thing a clamped height is meant to avoid. When
  // the badges arrive, having one of those puts the foot there too.
  const hasFoot = finding !== undefined || claim.evidence.length > 0;

  return (
    <article
      className="tile"
      data-kind={claim.kind}
      data-detail={detail}
      data-hypothesis={isHypothesis ? "yes" : "no"}
      style={{
        width: `${TILE_WIDTH}px`,
        height: `${height}px`,
        // How many lines of the claim to show. The same number the height was
        // worked out from, so the claim stops exactly where the box ends.
        ["--tile-claim-lines" as string]: `${lines}`,
      }}
      aria-label={`${KIND_WORDS[claim.kind]}: ${claim.claim}`}
    >
      <svg
        className="tile__outline"
        width={TILE_WIDTH}
        height={height}
        viewBox={`0 0 ${TILE_WIDTH} ${height}`}
        aria-hidden="true"
        focusable="false"
      >
        <path d={OUTLINES[claim.kind](height)} />
      </svg>

      {/* The sockets. An arrow that fires once and an arrow that has to keep
          holding are different claims about the world, so they arrive at
          different sockets and leave from different sockets — what a wire means
          is visible where it lands, before you follow it anywhere. */}
      <Handle
        type="target"
        position={Position.Left}
        id="in-trigger"
        className="tile__port tile__port--trigger"
        style={{ top: "38%" }}
      />
      <Handle
        type="target"
        position={Position.Left}
        id="in-sustain"
        className="tile__port tile__port--sustain"
        style={{ top: "62%" }}
      />
      <Handle
        type="source"
        position={Position.Right}
        id="out-trigger"
        className="tile__port tile__port--trigger"
        style={{ top: "38%" }}
      />
      <Handle
        type="source"
        position={Position.Right}
        id="out-sustain"
        className="tile__port tile__port--sustain"
        style={{ top: "62%" }}
      />

      <header className="tile__header">
        <span className="tile__kind">{KIND_WORDS[claim.kind]}</span>
        <time className="tile__resolves" dateTime={claim.resolvesBy}>
          {`resolves ${toDay(claim.resolvesBy)}`}
        </time>
      </header>

      <p className="tile__claim">{claim.claim}</p>

      <div className="tile__beliefs">
        <BeliefChip
          owner="model"
          slot={claim.beliefs.model}
          standing={claim.standing}
          versions={versions}
        />
        <BeliefChip owner="user" slot={claim.beliefs.user} />
        <BeliefChip owner="market" slot={claim.beliefs.market} />
      </div>

      {detail === "full" && hasFoot ? (
        // The foot of the tile. It is pushed to the bottom edge as one block, so
        // that on every tile alike the claim is at the top, the beliefs are in
        // the middle and whatever is left sits on the floor — and the eye can
        // read down a column without hunting for the line it wants.
        <div className="tile__foot">
          {finding === undefined ? null : <p className="tile__absence">{finding.reason}</p>}

          {claim.evidence.length === 0 ? null : (
            <ul className="tile__clippings">
              {claim.evidence.map((item) => (
                <Clipping
                  key={item.line}
                  monogram={item.monogram}
                  host={item.host}
                  line={item.line}
                  direction={item.direction}
                />
              ))}
            </ul>
          )}

          {/* Where a claim's badges go — *Supposed · Oct 1*, *Retracted · Oct 2
              · by "…"*, *Added*, *Retuned*. Empty here, because nothing on this
              screen can edit the map yet: the buttons that earn a badge arrive
              with the branch panel. The space is kept so that a tile does not
              change height the day they do. */}
          <div className="tile__badges" />
        </div>
      ) : null}
    </article>
  );
}

/**
 * One likelihood, with the range that says how sure we are of it — or, when
 * there is no likelihood, the absence and the reason for it.
 *
 * This is the smallest component in the product and the one carrying the most
 * of its honesty rule, so it is worth reading in full.
 *
 * **Two significant figures and the range, always.** A likelihood is printed as
 * `.35` and never as `.348` — a third figure claims an accuracy nobody has —
 * and it is never printed without the range under it. The rounding happens
 * here, once, at the moment of display; everything upstream carries the number
 * at full precision so that nothing is rounded twice.
 *
 * **What the range means, said out loud.** It is *how sure we are of the
 * number*, not how much the world can move. How much the world can move is
 * already inside the likelihood itself. That distinction is not a footnote: a
 * reader who takes a wide range to mean a volatile event has been misled by the
 * interface, so the model chip says which it is in its own label and spells it
 * out in full when you look at it.
 *
 * **An absent number is an absence, never a blank.** There is no path through
 * this component that prints nothing, prints a zero, or prints a stand-in. A
 * slot with no number shows the words for its absence and carries the reason
 * for it. A claim standing on the reader's own say-so shows the word — *Supposed
 * · Oct 1* — because while it is supposed it is true in every simulated world
 * and there is no number to show.
 */

import { useId, useState } from "react";
import type { BeliefOwner, Slot, Standing } from "../world";
import "./beliefChip.css";

/**
 * Print a number to two significant figures, the way this product prints one.
 *
 * A likelihood is between zero and one, so the leading zero is dropped: `.35`,
 * not `0.35`. Two significant figures means two digits that carry information,
 * and both of them are always printed — `.060` keeps its trailing nought,
 * because dropping it would claim less precision than we have, and "two figures
 * except when the second is a nought" would be a second rule for one ugly case.
 *
 * **It never prints a certainty.** Rounding to two figures turns .995 into
 * `1.0`, and nothing at all into `.0`, and both are claims nobody on this map
 * is entitled to make: one says the thing cannot fail, the other that it cannot
 * happen. So those two print as what they actually are, `>.99` and `<.01`. The
 * upper guard catches everything from .995 up, including 1 itself. The lower
 * one is rarer than it looks: two figures keeps two digits however small the
 * number gets, so `.0035` prints `.0035` and `.00012` prints `.00012`, and the
 * only value that would ever print as `.0` is exactly zero.
 *
 * **Why it does not use the obvious shortcut.** A computer stores .995 as
 * 0.99499999999999999556, so asking it directly for two figures gives `.99` —
 * under the guard, and the chip would print the one thing the rule forbids. So
 * the rounding is done on the number's own decimal digits instead: the shortest
 * decimal that reads back as this exact number, its point shifted by counting
 * rather than by multiplying, and then rounded half-up. `.995` shifts to
 * exactly 99.5, which rounds to 100, which is 1, which is `>.99`.
 *
 * @param value A likelihood, at full precision.
 * @returns The number as it is shown on screen.
 */
export function toTwoFigures(value: number): string {
  if (!Number.isFinite(value) || value <= 0) {
    return "<.01";
  }
  if (value >= 1) {
    return ">.99";
  }
  // The shortest decimal that reads back as this exact number, split into its
  // digits and where the point sits: .995 becomes "9.95" and -1.
  const [mantissa = "0", place = "0"] = value.toExponential().split("e");
  let exponent = Number(place);
  // The two figures, as a whole number from 10 to 99. Shifting the point in the
  // text and letting the parser read the result is what keeps .995 at 99.5
  // rather than a hair under it.
  let figures = Math.round(Number(`${mantissa}e1`));
  if (figures >= 100) {
    // Rounding up carried into the next place: .0999 becomes .10, not .100.
    figures = 10;
    exponent += 1;
  }
  if (exponent >= 0) {
    return ">.99";
  }
  return `.${"0".repeat(-exponent - 1)}${figures}`;
}

/**
 * Print a range the way this product prints one: `.22–.50`.
 *
 * The dash is an en dash, the one used for a span between two numbers.
 */
export function toRange(lo: number, hi: number): string {
  return `${toTwoFigures(lo)}–${toTwoFigures(hi)}`;
}

/**
 * The whole reading, in the form a sentence would use: `.35 (.22–.50)`.
 *
 * This is what the chip is called when it is read aloud, and what the tile uses
 * when it needs the reading inside a longer sentence.
 */
export function toReading(p: number, lo: number, hi: number): string {
  return `${toTwoFigures(p)} (${toRange(lo, hi)})`;
}

/** The word each owner is called by on screen. */
const OWNER_WORDS: Record<BeliefOwner, string> = {
  model: "model",
  user: "user",
  market: "market",
};

/**
 * The note a chip opens when you look at it: one label, one sentence.
 *
 * It is not a pop-up. It is a shelf that slides out from the bottom edge of the
 * tile, drawn on the tile's own surface, and it needs no dismissing — look
 * away, or move the keyboard on, and it closes itself.
 */
interface Note {
  /** The chip's label, printed as the first line of the shelf. */
  readonly label: string;
  /** The sentence under it. */
  readonly sentence: string;
}

/** Group a count in thousands the way the sentence below writes it: `2 000`. */
function inThousands(count: number): string {
  return count.toLocaleString("en-GB").replace(/,/g, " ");
}

/**
 * What the model chip says about itself — and there are two answers, because
 * there are two different things a range can be.
 *
 * **When a world computed these numbers**, the range came out of running the
 * map many times over, each run a coherent set of numbers the model would have
 * stood behind, and the sentence says so and then admits in its last clause
 * that nobody has checked the claim against anything that resolved.
 *
 * **When nothing computed them** — which is every number in this build, because
 * the engine's route does not exist yet — the range is what whoever wrote the
 * number down said about how sure they were. Saying "across 2 000 versions of
 * this map" over a number nobody ran through a map would be the plainest kind
 * of lie this product can tell, so it says the other thing instead.
 *
 * The chip picks between them by one fact: whether the world it is drawing
 * reports how many versions were run. Nothing else changes when the engine
 * lands.
 */
function modelNote(p: number, lo: number, hi: number, versions: number | undefined): Note {
  if (versions === undefined) {
    return {
      label: "stated range · not computed",
      sentence:
        "This range is stated, not computed — it says how sure the elicitation was. " +
        "Nothing has worked this number through the map yet.",
    };
  }
  return {
    label:
      `model interval, uncalibrated · how sure we are of ${toTwoFigures(p)} — ` +
      `not how much the world can move`,
    sentence:
      `Across ${inThousands(versions)} versions of this map — each one a set of numbers this ` +
      `model would have stood behind — the answer landed between ${toTwoFigures(lo)} and ` +
      `${toTwoFigures(hi)} eight times in ten. Nobody has checked whether that 8-in-10 holds ` +
      `up; no claim on this map has resolved yet.`,
  };
}

/** What the reader's own chip says about itself. */
function userNote(p: number, lo: number, hi: number): Note {
  return {
    label: `your own number · ${toReading(p, lo, hi)}`,
    sentence:
      "This is the number you gave. It sits beside the model's and the market's and is " +
      "never averaged with either of them.",
  };
}

/** What a market chip says about itself. */
function marketNote(lo: number, hi: number): Note {
  return {
    label: "market, as a venue is quoting it",
    sentence:
      `The likelihood is the middle of the best bid and the best offer; the range, ` +
      `${toRange(lo, hi)}, is the spread between them. It is what somebody will trade this ` +
      `claim at, not an opinion about it.`,
  };
}

/** Work out the three lines a chip shows, and the note behind it. */
function readChip(
  owner: BeliefOwner,
  slot: Slot,
  standing: Standing | undefined,
  versions: number | undefined,
): { reading: string; under: string | null; spoken: string; note: Note; numeric: boolean } {
  // A claim the reader has supposed true is true in every simulated world, so
  // the chip shows the word rather than a number. Inventing one — .98, or 1.0 —
  // would invite the reader to wonder about the other two per cent of a thing
  // they themselves declared settled.
  if (standing !== undefined) {
    return {
      reading: standing.words,
      under: null,
      spoken: `${OWNER_WORDS[owner]}: ${standing.words}`,
      note: { label: standing.words, sentence: standing.reason },
      numeric: false,
    };
  }

  if (slot.reading === undefined) {
    const absence = slot.absence;
    return {
      reading: absence.words,
      // The reader's own empty slot says what to do about it; every other
      // absence keeps its sentence for the shelf, where there is room for it.
      under: owner === "user" ? "add yours" : null,
      spoken: `${OWNER_WORDS[owner]}: ${absence.words}. ${absence.reason}`,
      note: { label: absence.words, sentence: absence.reason },
      numeric: false,
    };
  }

  const { p, lo, hi } = slot.reading;
  const note =
    owner === "model"
      ? modelNote(p, lo, hi, versions)
      : owner === "user"
        ? userNote(p, lo, hi)
        : marketNote(lo, hi);
  return {
    reading: toTwoFigures(p),
    under: toRange(lo, hi),
    spoken: `${OWNER_WORDS[owner]}: ${toReading(p, lo, hi)}`,
    note,
    numeric: true,
  };
}

/** What a belief chip needs to draw itself. */
export interface BeliefChipProps {
  /** Whose number this is. There are three, and they are never averaged. */
  readonly owner: BeliefOwner;
  /** The number, or the absence that stands where it would have been. */
  readonly slot: Slot;
  /** A word shown instead of a likelihood, when the claim stands on the reader's say-so. */
  readonly standing?: Standing;
  /**
   * How many versions of the map were run to produce this number.
   *
   * Absent means nothing computed it, and the model chip then says so rather
   * than describing a run that never happened.
   */
  readonly versions?: number;
}

/** One of the three belief chips on a tile. */
export function BeliefChip({ owner, slot, standing, versions }: BeliefChipProps) {
  const noteId = useId();
  const [pinned, setPinned] = useState(false);
  const { reading, under, spoken, note, numeric } = readChip(owner, slot, standing, versions);

  return (
    <span className="belief-chip" data-owner={owner} data-reading={numeric ? "number" : "words"}>
      {/* The face of the chip is the thing you can reach, so that looking at it
          with a pointer and arriving at it with the keyboard do the same thing.
          Pressing it pins the note open, for a reader who wants both hands free
          while they read it; pressing again puts it away. It is named by the
          whole reading — the number and its range together — because that is how
          the chip would be said out loud, and the range is never left off. */}
      <button
        className="belief-chip__face"
        type="button"
        aria-label={spoken}
        aria-describedby={noteId}
        aria-controls={noteId}
        aria-expanded={pinned}
        onClick={() => setPinned((was) => !was)}
      >
        <span className="belief-chip__owner">{OWNER_WORDS[owner]}</span>
        <span className="belief-chip__reading">{reading}</span>
        <span className="belief-chip__under">{under ?? ""}</span>
      </button>
      <span className="belief-chip__note" id={noteId} data-pinned={pinned ? "yes" : "no"}>
        <span className="belief-chip__note-label">{note.label}</span>
        <span className="belief-chip__note-sentence">{note.sentence}</span>
      </span>
    </span>
  );
}

