 * what the tool does, and a quiet strip of three rows reporting what the server
 * just told us. No cards with shadows, no buttons that do nothing, no
 * decoration. Density here follows the rule that there should be nothing
 * between the reader and the data.
 */

/* ---- Base ------------------------------------------------------------- */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body,
#root {
  margin: 0;
  padding: 0;
  /* The map fills the window, so the chain of boxes above it has to have a
   * height to fill. Without this the canvas collapses to nothing. */
  height: 100%;
}

body {
  background: var(--surface);
  color: var(--text);
  font-family: var(--font-interface);
  font-size: var(--text-md);
  font-weight: var(--weight-regular);
  line-height: 1.55;
  /* Fixed-width digits everywhere, so a number that changes never shifts the
   * text beside it (UX-11). */
  font-variant-numeric: tabular-nums;
  -webkit-font-smoothing: antialiased;
}

/* The keyboard ring. It is drawn on anything focusable, and it is drawn the
 * same way everywhere so it is never a surprise (UX-9, UX-12). */
:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
  border-radius: 2px;
}

/* ---- The page --------------------------------------------------------- */

.page {
  min-height: 100vh;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: var(--space-6) var(--space-3);

content.content:
  padding: var(--space-6) var(--space-3);
}

.column {
  width: 100%;
  max-width: 660px;
}

/* ---- The map screen ----------------------------------------------------- *
 * A bar across the top, the map filling everything under it, and one line at
 * the foot saying where every number on it came from. No padding around the
 * map: the map is the screen. */

.page--map {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  justify-content: flex-start;
  height: 100%;
  min-height: 0;
  padding: 0;
}

.map-bar {
  display: flex;
  align-items: baseline;
  gap: var(--space-3);
  padding: var(--space-2) var(--space-3);
  border-bottom: 1px solid var(--hairline);
  background: var(--surface-raised);
}

/* A word with an arrow in front of it, not a button with a fill. The only thing
 * on this bar that does anything, so it does not need to shout. */
.map-bar__back {
  padding: 0;
  margin: 0;
  border: none;
  background: none;
  font-family: inherit;
  font-size: var(--text-sm);
  color: var(--text-muted);
  cursor: pointer;
}

.map-bar__back:hover {
  color: var(--text);
}

.map-bar__title {
  margin: 0;
  font-size: var(--text-md);
  font-weight: var(--weight-semibold);
  letter-spacing: -0.01em;
  color: var(--text);
}

/* Where every number on the map came from, in one sentence, under the map. A
 * map whose numbers cannot say where they came from is the state this product
 * refuses to show, so the sentence is part of the map rather than a footnote
 * somebody might have left off. */
.map-origin {
  margin: 0;
  padding: var(--space-1) var(--space-3);
  border-top: 1px solid var(--hairline);
  background: var(--surface-raised);
  font-size: var(--text-sm);
  color: var(--text-muted);
  text-wrap: pretty;
}

